(() => {
  'use strict';
  const J=window.Jeebtak, KEY='jeebtak.v1', $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icons={home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',subscriptions:'M4 6h16v14H4z M7 3h10 M10 10l5 3-5 3z',bills:'M6 3h12v18l-3-2-3 2-3-2-3 2z M9 7h6 M9 11h6 M9 15h3',salary:'M3 7h18v13H3z M7 7V4h10v3 M3 12c5 5 13 5 18 0 M10 13h4',debts:'M4 5h16v16H4z M7 3v4 M17 3v4 M4 10h16 M8 14h2 M14 14h2 M8 17h2',transactions:'M4 7h15m-4-4 4 4-4 4 M20 17H5m4-4-4 4 4 4',reports:'M4 20V10h4v10 M10 20V4h4v16 M16 20v-7h4v7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 3h4l1 3 3-1 2 4-2 2v2l2 2-2 4-3-1-1 3h-4l-1-3-3 1-2-4 2-2v-2L4 9l2-4 3 1z',more:'M5 12h.01 M12 12h.01 M19 12h.01',bell:'M6 9a6 6 0 0 1 12 0c0 7 3 7 3 9H3c0-2 3-2 3-9 M9 21h6',plus:'M12 5v14 M5 12h14',arrow:'M18 12H6m5-5-5 5 5 5',up:'M7 17 17 7 M7 7h10v10',down:'M7 7l10 10 M7 17h10V7',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z M8 12l3 3 5-6',calendar:'M5 5h14v16H5z M8 3v5 M16 3v5 M5 10h14',check:'M5 12l4 4L19 6',close:'m6 6 12 12 M6 18 18 6',edit:'m4 16 11-11 4 4L8 20H4z M13 7l4 4',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',download:'M12 3v12m-4-4 4 4 4-4 M4 15v6h16v-6',upload:'M12 16V4m-4 4 4-4 4 4 M4 15v6h16v-6',wallet:'M3 7h17v14H3z M3 7V4h14v3 M16 12h5v5h-5z',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',lock:'M5 10h14v11H5z M8 10V7a4 4 0 0 1 8 0v3 M12 14v3',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',search:'M17 17l4 4 M19 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',cloud:'M7 19a5 5 0 1 1 0-10 7 7 0 0 1 13 1 4.5 4.5 0 0 1-1 9z',play:'m9 5 11 7-11 7z',pause:'M8 4v16 M16 4v16',refresh:'M20 7v5h-5 M4 17v-5h5 M20 12a8 8 0 0 0-14-5 M4 12a8 8 0 0 0 14 5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'};
  const icon=(n,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[n]||icons.wallet}"/></svg>`;
  const art=n=>`<img src="assets/${n==='debts'?'debt':n}.svg" alt="" aria-hidden="true">`;
  const labels={dashboard:'نظرة عامة',subscriptions:'الاشتراكات',bills:'الفواتير',salary:'الراتب',debts:'الالتزامات',transactions:'الحركات',reports:'التقارير',settings:'الإعدادات',more:'المزيد',notifications:'التنبيهات'};
  let state=J.empty(),lastRaw=null,broken=false,demo=false,locked=false,route='dashboard',subFilter='active',selectedMonth=J.month(),txFilter='all',search='',dialogAction=null,lastFocus=null,importCandidate=null,toastTimer;
  function load(){state=J.empty();locked=false;broken=false;try{lastRaw=localStorage.getItem(KEY);if(lastRaw){const raw=JSON.parse(lastRaw);state=J.validate(raw);if(raw.settings.pin&&/^[a-f0-9]{64}$/.test(raw.settings.pin.hash)&&/^[a-f0-9]{32}$/.test(raw.settings.pin.salt))state.settings.pin=raw.settings.pin;locked=!!state.settings.pin;}}catch(e){broken=true;state=J.empty();}}
  load();
  const sync=window.JeebtakSync?new window.JeebtakSync.Engine({
    validate:raw=>J.validate(raw||J.empty()),
    active:()=>!demo&&!broken&&!locked&&!document.hidden&&!modal.open&&!document.activeElement?.closest('form'),
    onApply:()=>{const wasLocked=locked;load();locked=wasLocked;render();},
    onStatus:()=>{for(const el of document.querySelectorAll('[data-sync-status]'))el.textContent=sync.message;for(const el of document.querySelectorAll('[data-sync-review]'))el.hidden=sync.status!=='conflict';}
  }):null;
  function syncPanel(){return `<div class="panel setting-block sync-panel"><h2>${icon('cloud')} محفظتك على كل أجهزتك</h2><p data-sync-status role="status">${esc(sync?.message||'المزامنة غير متاحة في هذه النسخة')}</p><p class="fine">تشفير قبل الرفع. تحديث كل ٥ ثوانٍ أثناء فتح جيبتك؛ وبعد العودة للنت. رمز PIN والمظهر خاصان بكل جهاز.</p><div class="form-actions">${sync?.connected()?button('ربط جهاز آخر','sync-code','','secondary')+button('مزامنة الآن','sync-now','','secondary')+button('فصل هذا الجهاز','sync-disconnect','','secondary'):button('ربط بالمحفظة الخاصة','sync-pair')}</div><button type="button" class="btn secondary" data-action="sync-conflict" data-sync-review ${sync?.status==='conflict'?'':'hidden'}>مراجعة اختلاف النسختين</button><p class="fine">رمز الربط مفتاح الوصول لمحفظتك. احفظه بمكان خاص ولا تشاركه.</p>${localStorage.getItem('jeebtak.sync.recovery.v1')?button('تنزيل نسخة الإنقاذ قبل المزامنة','sync-recovery','','secondary'):''}</div>`;}
  function pairForm(){if(demo)throw Error('اخرج من الوضع التجريبي لربط بياناتك الحقيقية.');if(location.protocol!=='https:'||!sync||!crypto.subtle||!navigator.locks)throw Error('الربط يحتاج رابط HTTPS ومتصفحاً حديثاً.');openModal('ربط جهازك بمحفظتك',`<p class="modal-intro">ألصق رمز الربط الخاص. أول ربط يحتفظ بنسخة إنقاذ محلية، وإذا اختلفت البيانات رح تختار النسخة المعتمدة قبل أي استبدال.</p><label class="field full">رمز الربط<textarea name="pairCode" dir="ltr" rows="4" required autocomplete="off" spellcheck="false"></textarea></label>`,async fd=>{await sync.pair(fd.get('pairCode'));closeModal();render();await sync.tick();},'ربط هذا الجهاز');}
  function conflictForm(){const conflict=sync?.conflict;if(!conflict){sync?.tick();toast('جارٍ التحقق من أحدث النسخ؛ افتح المراجعة بعد لحظة.');return;}const info=s=>`${s.transactions.length} حركة، ${s.subscriptions.length} اشتراك، ${s.bills.length} فاتورة، ${s.debts.length} التزام`;openModal('في نسختين مختلفتين',`<p class="modal-intro">ما استبدلنا أي بيانات. اختر النسخة الكاملة المعتمدة؛ لن ندمج دفعات مالية تلقائياً. نزّل النسختين وراجعهما أولاً إذا عدّلت على الجهازين.</p><div class="detail-pairs"><div><span>هذا الجهاز</span><strong>${info(conflict.local)}</strong></div><div><span>المحفظة السحابية</span><strong>${info(conflict.remote)}</strong></div></div><div class="form-actions">${button('تنزيل النسختين للمراجعة','sync-copies','','secondary')}</div><label class="field full">النسخة التي تريد اعتمادها<select name="choice" required><option value="">اختر بعد المراجعة</option value="remote">نسخة المحفظة السحابية على هذا الجهاز</option><option value="local">نسخة هذا الجهاز على كل الأجهزة</option></select></label><p class="fine">سنحتفظ بنسخة إنقاذ قبل الاستبدال. النسخة غير المختارة لن تُدمج تلقائياً.</p>`,async fd=>{const choice=fd.get('choice');if(!['local','remote'].includes(choice))throw Error('اختر النسخة المعتمدة.');closeModal();await sync.tick(choice);render();toast(sync.message);},'اعتماد النسخة المختارة');}

  const n=(x,d=2)=>new Intl.NumberFormat('en-US',{minimumFractionDigits:0,maximumFractionDigits:d}).format(Number(x)||0);
  const units={JOD:'د.أ',USD:'$',IQD:'د.ع'},digits={JOD:3,USD:2,IQD:0};
  const money=(v,c=state.settings.base,animate=false)=>`<bdi class="money"><span${animate?` data-count="${Number(v)}" data-digits="${digits[c]}"`:''}>${n(v,digits[c])}</span><span class="unit">${units[c]}</span></bdi>`;
  const converted=(amount,currency)=>`${money(J.convert(state,amount,currency))}${currency!==state.settings.base?`<span class="original">${money(amount,currency)} <span>بالعملة الأصلية</span></span>`:''}`;
  const formatDate=(d,year=false)=>new Intl.DateTimeFormat('ar-JO',{day:'numeric',month:'long',...(year?{year:'numeric'}:{})}).format(J.date(d));
  const monthName=m=>new Intl.DateTimeFormat('ar-JO',{month:'long',year:'numeric'}).format(J.date(`${m}-01`));
  const monthShort=m=>new Intl.DateTimeFormat('ar-JO',{month:'short'}).format(J.date(`${m}-01`));
  const button=(text,action,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
  const iButton=(name,action,title,extra='')=>`<button type="button" class="icon-button" data-action="${action}" aria-label="${title}" title="${title}" ${extra}>${icon(name)}</button>`;
  const title=(h,sub,side='')=>`<div class="page-heading"><div><h1>${h}</h1><p>${sub}</p></div>${side}</div>`;
  const empty=(h,p,action='',text='',a='wallet-hero')=>`<div class="empty">${art(a)}<h3>${h}</h3><p>${p}</p>${action?button(text,action):''}</div>`;
  const cycleLabel=c=>({1:'شهري',3:'كل ٣ أشهر',6:'كل ٦ أشهر',12:'سنوي'}[c]);
  const dueBadge=d=>{const days=J.dayDiff(d);return `<span class="badge ${days<0?'late':days<=3?'warn':''}">${days<0?`متأخر ${Math.abs(days)} يوم`:days===0?'اليوم':days===1?'بكرا':`بعد ${days} أيام`}</span>`;};
  function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
  function applyTheme(){const theme=state.settings.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):state.settings.theme;document.documentElement.dataset.theme=theme;$('meta[name="apple-mobile-web-app-status-bar-style"]').content=theme==='dark'?'black-translucent':'default';$('meta[name="theme-color"]').content=theme==='dark'?'#10231c':'#194c40';}
  function commit(fn){if(broken)throw new Error('استعد نسخة احتياطية أو نزّل البيانات المتضررة أولاً من الإعدادات.');if(!demo&&localStorage.getItem(KEY)!==lastRaw){toast('تغيّرت البيانات في نافذة أخرى. أعد فتح النموذج بعد التحديث.');load();render();throw new Error('تغيّرت البيانات في نافذة أخرى.');}const next=JSON.parse(JSON.stringify(state));fn(next);next.updatedAt=new Date().toISOString();if(!demo){const raw=JSON.stringify(next);try{localStorage.setItem(KEY,raw);}catch(e){throw new Error('تعذّر الحفظ على الجهاز. صدّر نسخة احتياطية وتحقق من المساحة وإعدادات المتصفح.');}lastRaw=raw;}state=next;applyTheme();if(!demo&&sync?.connected())sync.notify('pending','محفوظ هنا؛ بانتظار المزامنة');}
  function avatar(x,type){const name=x.name.toLowerCase();if(type==='subscriptions'&&name.includes('netflix'))return '<span class="item-avatar netflix" aria-hidden="true">N</span>';if(type==='subscriptions'&&name.includes('spotify'))return `<span class="item-avatar spotify">${icon('subscriptions')}</span>`;if(name.includes('icloud'))return `<span class="item-avatar cloud">${icon('cloud')}</span>`;return `<span class="item-avatar">${art(type==='general'?'salary':type)}</span>`;}
  function upcomingItems(items,limit=5,reminderActions=false,pick=false){return items.slice(0,limit).map(o=>`<div class="list-item">${pick?`<input type="checkbox" class="settle-pick" value="${o.type}:${esc(o.id)}:${esc(o.period)}" aria-label="تحديد ${esc(o.name)}">`:''}${avatar(o,o.type)}<div class="grow"><div class="item-name">${esc(o.name)}</div><div class="item-meta">${formatDate(o.date)} ${dueBadge(o.date)}</div></div><div class="item-amount">${converted(o.amount,o.currency)}</div>${reminderActions&&o.type==='subscriptions'?`<div class="reminder-actions">${button('جدّد','pay',`data-type="${o.type}" data-id="${esc(o.id)}" data-period="${o.period}"`,'small-btn')}${button('ألغِ','cancel-sub',`data-id="${esc(o.id)}"`,'secondary small-btn')}</div>`:iButton('check','pay','تسجيل الدفع',`data-type="${o.type}" data-id="${esc(o.id)}" data-period="${o.period}"`)}</div>`).join('');}
  function donut(m){const data=J.report(state,m),total=Object.values(data).reduce((a,b)=>a+b,0),colors={subscriptions:'#bd8e67',bills:'#4a7965',debts:'#8faa84',general:'#dbc8a4'};let cumulative=0;const gradient=Object.entries(data).filter(([,v])=>v>0).map(([k,v])=>{let start=cumulative;cumulative+=v/total*100;return `${colors[k]} ${start}% ${cumulative}%`;}).join(',');return `<div class="donut-wrap"><div class="donut" role="img" aria-label="توزيع المصروف المسجل لهذا الشهر" style="${total?`background:conic-gradient(${gradient})`:''}"><div class="donut-center"><small>مجموع المصروف</small><strong>${money(total)}</strong><small>${monthShort(m)}</small></div></div><div class="chart-legend">${Object.entries(data).map(([k,v])=>`<div><i class="dot" style="background:${colors[k]}"></i><span>${J.categoryNames[k]}</span><b>${money(v)}</b></div>`).join('')}</div></div>`;}
  function dashboard(){const s=J.summary(state),up=J.occurrences(state,J.addDays(J.today(),14)),noData=!state.salary.amount&&!state.transactions.length&&!state.subscriptions.length&&!state.bills.length;const ratio=Math.round(s.ratio*100);
    return title('يا هلا، خلّينا نطمن عَ جيبتك','كل شي إلك وعليك، بنظرة واحدة.',`<span class="month-chip">${icon('calendar')}${monthName(J.month())}</span>`)+
    (noData?`<div class="banner">${icon('wallet')}<div class="grow"><strong>جيبتك جديدة، وبدايتها بإيدك</strong>أدخل رصيدك وراتبك، أو جرّب التطبيق ببيانات توضيحية.</div>${button('إعداد جيبتك','setup','', 'small-btn')}${button('جرّب أولاً','demo','','secondary small-btn')}</div>`:'')+
    `<section class="hero-grid"><div class="pocket"><div class="pocket-label">${icon('wallet')}الرصيد الحالي</div><div class="pocket-balance">${money(s.balance,undefined,true)}</div><p class="pocket-note">من الدخل والدفعات المسجّلة فعلياً</p><img class="wallet-art" src="assets/wallet-hero.svg" alt="محفظة جيبتك الجلدية الخضراء"><div class="pocket-footer"><span>${icon('shield')}على جهازك، وبس</span><span>${icon('refresh')}آخر تحديث ${state.updatedAt?new Intl.DateTimeFormat('ar-JO',{hour:'numeric',minute:'2-digit'}).format(new Date(state.updatedAt)):'الآن'}</span></div></div><div class="available"><div class="available-label">${icon('check')}المتاح للصرف</div><div class="available-value ${s.available<0?'negative':''}">${money(s.available,undefined,true)}</div><p class="available-desc">بعد حجز الاستحقاقات غير المدفوعة حتى نهاية الشهر</p><div class="available-bottom">${icon(s.available<0?'info':'shield')}<p>${s.available<0?'الالتزامات أعلى من رصيدك الحالي. خلّينا نراجع الأقرب.':s.reserved?'استحقاقاتك محسوبة. هاد اللي بتقدر تتصرف فيه.':'كل دفعة بتسجّلها بتخلي الصورة أوضح.'}</p></div></div></section>
    <section class="stat-row">${[[s.income,'الدخل المستلم','down',''],[s.expense,'المصروف هالشهر','up','expense'],[s.reserved,'محجوز للاستحقاقات','calendar','reserve']].map(([v,l,i,c])=>`<div class="stat"><span class="stat-symbol ${c}">${icon(i)}</span><div><div class="stat-label">${l}</div><div class="stat-value">${money(v,undefined,true)}</div></div></div>`).join('')}</section>
    <section class="dashboard-grid"><div class="stack"><div><div class="panel-heading"><h2>على السريع</h2><span class="fine">خطوة صغيرة، فرق كبير</span></div><div class="quick-actions">${[['مصروف جديد','add-expense','debt'],['إضافة دخل','add-income','salary'],['فاتورة جديدة','add-bill','bills'],['اشتراك جديد','add-sub','subscriptions']].map(([l,a,i])=>`<button class="quick-action" data-action="${a}">${art(i)}<span>${l}</span></button>`).join('')}</div><div class="panel"><div class="panel-heading"><div><h2>قدّيش محجوز من راتبك؟</h2><p>المتوسط الشهري للالتزامات الثابتة</p></div><span class="meter-figure ${ratio>70?'negative':''}">${s.net?ratio:'—'}<small> %</small></span></div><div class="row between"><span class="fine">${money(s.totalFixed)} التزامات</span><span class="fine">من ${money(s.net)} صافي الراتب</span></div><div class="meter">${Object.entries(s.fixed).map(([k,v])=>`<span class="segment-${k==='subscriptions'?'sub':k==='bills'?'bill':'debt'}" style="width:${s.net?Math.min(100,v/Math.max(s.totalFixed,s.net)*100):0}%"></span>`).join('')}</div><div class="legend"><span><i class="dot segment-sub"></i>اشتراكات</span><span><i class="dot segment-bill"></i>فواتير</span><span><i class="dot segment-debt"></i>التزامات</span></div><div class="gentle-note">${icon('info')}<span>${!s.net?'أضف راتبك الصافي حتى تعرف نسبة التزاماتك.':ratio>70?'جزء كبير من الراتب محجوز. راجع الاشتراكات اللي ما بتستخدمها.':'هاي نسبة تخطيطية؛ الاشتراكات السنوية موزّعة على ١٢ شهر.'}</span></div></div></div><div class="panel"><div class="panel-heading"><h2>وين راحت المصاري؟</h2><a href="#reports" class="text-btn">التقرير الكامل ${icon('arrow')}</a></div>${donut(J.month())}</div></div>
    <div class="stack"><div class="panel"><div class="panel-heading"><div><h2>قريباً على جيبتك</h2><p>الـ ١٤ يوم الجايين، وأي متأخرات</p></div><span class="badge">${up.length} استحقاق</span></div><div class="item-list">${up.length?upcomingItems(up):empty('ما في شي مستعجل','رح تلاقي هون أقرب فواتيرك وتجديداتك.','','','bills')}</div>${up.length>5?`<a href="#notifications" class="text-btn">عرض كل الاستحقاقات ${icon('arrow')}</a>`:''}<div class="due-month">${up.length?`مجموع القادم ${money(up.reduce((a,x)=>a+J.convert(state,x.amount,x.currency),0))}`:'مساحة أهدأ لمصاريك'}</div></div><div class="panel"><div class="panel-heading"><h2>آخر الحركات</h2><a href="#transactions" class="text-btn">الكل ${icon('arrow')}</a></div>${state.transactions.length?state.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(t=>`<div class="list-item"><span class="stat-symbol ${t.kind==='income'?'':'expense'}">${icon(t.kind==='income'?'down':'up')}</span><div class="grow"><div class="item-name">${esc(t.name)}</div><div class="item-meta">${formatDate(t.date)}</div></div><div class="item-amount ${t.kind==='income'?'positive':''}">${t.kind==='income'?'+':'−'} ${converted(t.amount,t.currency)}</div></div>`).join(''):empty('أول حركة بتبدأ الصورة','سجّل مصروفك أو دخلك، وخلي الباقي علينا.','add-expense','إضافة حركة','salary')}</div></div></section>`;
  }
  function subscriptions(){const active=state.subscriptions.filter(x=>x.status==='active'),monthly=active.reduce((a,x)=>a+J.convert(state,x.amount/x.cycle,x.currency),0),saved=state.subscriptions.reduce((a,x)=>a+J.savings(state,x),0),unused=active.filter(x=>J.dayDiff(J.today(),x.lastUsed)>=30);const filtered=state.subscriptions.filter(x=>subFilter==='unused'?unused.includes(x):x.status===subFilter);
    return title('اشتراكاتك، على بالِك','خلي اللي بتستخدمه. ووفّر اللي ما إله داعي.',button(`${icon('plus')} اشتراك جديد`,'add-sub'))+`<section class="summary-strip"><div class="summary-tile"><div class="label">متوسط الاشتراكات الشهري</div><div class="value">${money(monthly)}</div></div><div class="summary-tile"><div class="label">التكلفة السنوية التقديرية</div><div class="value">${money(monthly*12)}</div></div><div class="summary-tile">${art('subscriptions')}<div class="label">تجديدات تجنّبتها بعد الإلغاء</div><div class="value positive">${money(saved)}</div></div></section>${unused.length?`<div class="banner warning">${icon('info')}<div class="grow"><strong>${unused.length} اشتراك بدون استخدام مؤكّد من ٣٠ يوم</strong>راجعهم، يمكن في مصاري ترجع لجيبتك.</div>${button('مراجعة الاشتراكات','sub-filter','data-filter="unused"','secondary small-btn')}</div>`:''}<div class="tabs" aria-label="حالة الاشتراكات">${[['active','نشطة'],['paused','مجمّدة'],['cancelled','الملغيات'],['unused','غير مستخدمة']].map(([k,l])=>`<button data-action="sub-filter" data-filter="${k}" class="${subFilter===k?'active':''}" aria-pressed="${subFilter===k}">${l}</button>`).join('')}</div><section class="cards-grid">${filtered.map((x,i)=>`<article class="subscription-card" style="animation-delay:${Math.min(i,6)*55}ms"><div class="row">${avatar(x,'subscriptions')}<div class="grow"><h3>${esc(x.name)}</h3><div class="fine">${esc(x.category)}</div></div>${iButton('edit','edit-sub','تعديل الاشتراك',`data-id="${esc(x.id)}"`)}</div><div class="subscription-price">${converted(x.amount,x.currency)}<small>/ ${cycleLabel(x.cycle)}</small></div><div class="card-divider"></div><div class="row between"><span class="fine">${x.status==='cancelled'?'تاريخ الإلغاء':'التجديد القادم'}</span><span class="small">${formatDate(x.cancelledDate&&x.status==='cancelled'?x.cancelledDate:x.nextDate)}</span></div><div class="row between" style="margin-top:8px"><span class="fine">آخر دفعة</span><span class="small">${x.lastPaid?formatDate(x.lastPaid):'لم تُسجّل بعد'}</span></div><div class="row between" style="margin-top:8px"><span class="fine">آخر استخدام ${formatDate(x.lastUsed)}</span>${x.status==='active'?`<button class="text-btn" data-action="used" data-id="${esc(x.id)}">استخدمته اليوم ${icon('check')}</button>`:`<span class="badge">${x.status==='cancelled'?'ملغي':'مجمّد'}</span>`}</div>${x.status==='cancelled'?`<div class="gentle-note">${icon('info')}<span>وفّر الإلغاء ${money(J.savings(state,x))} من التجديدات التي حل موعدها. تقدير، وليس مبلغاً أُضيف للرصيد.</span></div>`:''}<div class="card-footer">${x.status==='active'?button('جدّد وسجّل الدفع','pay',`data-type="subscriptions" data-id="${esc(x.id)}" data-period="${x.nextDate}"`,'small-btn')+iButton('pause','pause-sub','تجميد',`data-id="${esc(x.id)}"`)+iButton('close','cancel-sub','إلغاء الاشتراك',`data-id="${esc(x.id)}"`):button('إعادة التفعيل','resume-sub',`data-id="${esc(x.id)}"`,'secondary small-btn')}</div></article>`).join('')}</section>${!filtered.length?`<div class="panel">${empty(subFilter==='active'?'اشتراك إله قيمة، ومصروف إله معنى':'القائمة فاضية حالياً',subFilter==='active'?'أضف أول اشتراك وحدّد موعده. من هون بتتابع التجديد والاستخدام.':'كل الاشتراكات اللي بهالحالة رح تظهر هون.','add-sub','إضافة اشتراك','subscriptions')}</div>`:''}`;
  }
  function monthControl(){return `<div class="month-control">${iButton('arrow','prev-month','الشهر السابق')}<input aria-label="الشهر المعروض" type="month" id="month-select" value="${selectedMonth}" max="${J.month()}">${iButton('arrow','next-month','الشهر التالي','style="transform:rotate(180deg)"')}</div>`;}
  function bills(){const m=selectedMonth;return title('فواتير مرتّبة، بال أهدى','المبلغ المتوقع للتخطيط، والفعلي عند الدفع.',button(`${icon('plus')} فاتورة جديدة`,'add-bill'))+`<div class="panel-heading">${monthControl()}<span class="fine">حالة كل فاتورة لشهرها</span></div><section class="content-two"><div class="stack">${state.bills.filter(x=>!x.archived).map(x=>{const tx=state.transactions.find(t=>t.sourceType==='bills'&&t.sourceId===x.id&&t.period===m),due=J.dueInMonth(m,x.dueDay),applicable=due>=x.startDate,settled=!!x.settledThrough&&m<=x.settledThrough;return `<article class="bill-row"><div class="row">${avatar(x,'bills')}<div><h3>${esc(x.name)}</h3><div class="item-meta">${formatDate(due)} ${tx?'<span class="badge ok">مدفوعة</span>':!applicable?'<span class="badge">قبل بداية الفاتورة</span>':settled?'<span class="badge ok">مسدّدة سابقاً</span>':dueBadge(due)}</div></div></div><div class="item-amount">${converted(tx?.amount??x.amount,x.currency)}<span class="original">${tx?'المبلغ الفعلي':'المبلغ المتوقع'}</span></div><div class="actions"><button class="text-btn" data-action="bill-history" data-id="${esc(x.id)}">${icon('reports')} سجل الفاتورة</button>${iButton('edit','edit-bill','تعديل الفاتورة',`data-id="${esc(x.id)}"`)}${iButton('trash','archive-bill','أرشفة الفاتورة',`data-id="${esc(x.id)}"`)}${!tx&&applicable&&!settled?button('تسجيل الدفع','pay',`data-type="bills" data-id="${esc(x.id)}" data-period="${m}"`,'small-btn'):tx?'<span class="badge ok">تم الدفع</span>':''}</div></article>`;}).join('')||`<div class="panel">${empty('الكهرباء، النت، والإيجار…','رتّب الفواتير مرة، وتابعها كل شهر.','add-bill','إضافة أول فاتورة','bills')}</div>`}</div><div class="stack"><div class="panel"><div class="panel-heading"><h2>فاتورة شهر، ما بتضيع</h2>${art('bills').replace('<img','<img class="header-figure"')}</div><p class="fine">عند الدفع، أدخل المبلغ الفعلي. بنحتفظ بالدفعة لشهر استحقاقها، حتى لو دفعتها متأخر. كل فاتورة إلها رسم وسجل مستقل.</p><div class="gentle-note">${icon('bell')}التذكير حسب الأيام اللي حدّدتها، وبيظهر عند فتح جيبتك.</div></div><div class="panel"><h2>الأرشيف</h2>${state.bills.filter(x=>x.archived).map(x=>`<div class="list-item"><div class="grow"><div class="item-name">${esc(x.name)}</div></div><button class="text-btn" data-action="bill-history" data-id="${esc(x.id)}">السجل</button><button class="text-btn" data-action="restore-bill" data-id="${esc(x.id)}">استعادة</button></div>`).join('')||'<p class="fine" style="margin-top:12px">الفواتير المؤرشفة بتحتفظ بكل دفعاتها.</p>'}</div></div></section>`;}
  function salary(){const s=J.summary(state),sal=state.salary,deds=sal.deductions.filter(d=>d.recurring||d.month===selectedMonth),net=J.netSalary(state,selectedMonth),received=J.hasPaid(state,'salary','salary',selectedMonth);return title('راتبك، من أول دينار','الصافي واضح، وكل استقطاع إله مكان.',button(`${icon('edit')} تعديل الراتب`,'edit-salary'))+`<div class="panel-heading">${monthControl()}</div><section class="content-two"><div class="stack"><div class="panel receipt-panel"><div class="panel-heading"><div><h2>قسيمة ${monthName(selectedMonth)}</h2><p>موعد الراتب: يوم ${sal.payDay} من الشهر</p></div>${art('salary').replace('<img','<img class="header-figure"')}</div><div class="detail-pairs"><div><span>الراتب الإجمالي</span><strong>${converted(sal.amount,sal.currency)}</strong></div>${deds.map(d=>`<div><span>${esc(d.name)}</span><span>− ${money(d.amount,sal.currency)}</span></div>`).join('')}<div class="total-line"><span>الراتب الصافي</span><strong>${money(net,sal.currency)}</strong></div></div><div class="form-actions">${received?'<span class="badge ok">تم تسجيل استلام راتب هذا الشهر</span>':button('تسجيل استلام الراتب','receive-salary',net<=0?'disabled':'')}</div><div class="gentle-note">${icon('info')}يتغيّر الرصيد عند تسجيل الاستلام فقط. بنضيف الصافي مرة واحدة بعد الاستقطاعات.</div></div><div class="panel"><div class="panel-heading"><h2>الاستقطاعات</h2>${button(`${icon('plus')} استقطاع`,'add-deduction','','secondary small-btn')}</div>${sal.deductions.map(d=>`<div class="list-item"><div class="grow"><div class="item-name">${esc(d.name)}</div><div class="item-meta">${d.recurring?'يتكرر كل شهر':monthName(d.month)}</div></div><div class="item-amount">${money(d.amount,sal.currency)}</div>${iButton('edit','edit-deduction','تعديل الاستقطاع',`data-id="${esc(d.id)}"`)}${iButton('trash','delete-deduction','حذف الاستقطاع',`data-id="${esc(d.id)}"`)}</div>`).join('')||'<p class="fine">ضمان اجتماعي، تأمين، ضريبة… أضف كل بند لحاله.</p>'}<div class="gentle-note">${icon('info')}إذا القسط مخصوم من راتبك، سجّله هون فقط لتتجنّب حجزه مرة ثانية بقسم الالتزامات.</div></div></div><div class="panel" style="align-self:start"><h2>شو بيضل من الراتب؟</h2><p class="fine" style="margin-top:7px">تخطيط شهري بالأسعار الحالية</p><div class="rule"></div><div class="detail-pairs"><div><span>صافي الراتب</span><strong>${money(J.convert(state,net,sal.currency))}</strong></div>${Object.entries(s.fixed).map(([k,v])=>`<div><span>${J.categoryNames[k]}</span><span>− ${money(v)}</span></div>`).join('')}<div class="total-line"><span>المتبقي المخطط</span><strong class="${J.convert(state,net,sal.currency)-s.totalFixed<0?'negative':'positive'}">${money(J.convert(state,net,sal.currency)-s.totalFixed)}</strong></div></div><div class="gentle-note">${icon('info')}الاشتراكات السنوية موزّعة شهرياً هنا. المتاح الفعلي للصرف بتلاقيه بالرئيسية.</div></div></section>`;}
  function debts(){const debtList=state.debts.filter(x=>!x.archived);return title('خطوة أقرب لراحة البال','أقساطك وديونك، ونهاية واضحة بالطريق.',button(`${icon('plus')} التزام جديد`,'add-debt'))+`<section class="cards-grid">${debtList.map(x=>{const perc=x.bank?.paidPercent??Math.round((x.total-x.remaining)/x.total*100),months=Math.ceil(x.remaining/x.installment),next=J.occurrences(state,J.addMonths(x.startDate>J.today()?x.startDate:J.today(),2)).find(o=>o.id===x.id),end=x.bank?.endDate||(months?J.addMonths(next?.date||J.dueInMonth(J.month(),x.dueDay),months-1,x.dueDay):J.today());return `<article class="subscription-card"><div class="row">${avatar(x,'debts')}<div class="grow"><h3>${esc(x.name)}</h3><div class="fine">${x.remaining?'قسط شهري':'مكتمل، يعطيك العافية'}${x.settledThrough?` · مسدّد حتى ${monthName(x.settledThrough)}`:''}</div></div>${iButton('edit','edit-debt','تعديل الالتزام',`data-id="${esc(x.id)}"`)}</div><div class="subscription-price">${converted(x.remaining,x.currency)}</div><div class="fine">${x.bank?'أصل القرض':'متبقي من'} ${money(x.total,x.currency)}</div><div class="meter"><span class="segment-bill" style="width:${perc}%"></span></div><div class="row between fine"><span>${x.bank?'السداد حسب البنك':'تم سداد'} ${perc}%</span><span>${x.bank?`${x.bank.termMonths} شهر مدة العقد`:`${months} دفعة تقريباً`}</span></div><div class="card-divider"></div><div class="detail-pairs"><div><span>القسط الشهري</span><span>${money(x.bank?x.installment:Math.min(x.installment,x.remaining),x.currency)}</span></div><div><span>${x.bank?'نهاية العقد حسب البنك':'النهاية المتوقعة'}</span><span>${formatDate(end,true)}</span></div></div>${x.bank?`<details class="bank-details"><summary>تفاصيل جدول البنك</summary><div class="detail-pairs"><div><span>الفائدة السنوية / APR</span><bdi>${x.bank.apr}%</bdi></div><div><span>مجموع الفوائد</span>${money(x.bank.interest,x.currency)}</div><div><span>العمولات والرسوم</span>${money(x.bank.fees,x.currency)}</div><div><span>القسط الأخير</span>${money(x.bank.lastInstallment,x.currency)}</div><div><span>تاريخ بداية القرض</span>${formatDate(x.startDate,true)}</div></div><p class="fine">نسبة البنك مدخلة يدوياً، وليست نسبة انخفاض أصل القرض. الرصيد يُطابق كشف البنك عند تسجيل كل قسط.</p></details>`:''}<div class="card-footer">${x.remaining&&next?button('تسجيل قسط','pay',`data-type="debts" data-id="${esc(x.id)}" data-period="${next.period}"`,'small-btn'):'<span class="badge ok">مكتمل</span>'}${iButton('trash','archive-debt','أرشفة الالتزام',`data-id="${esc(x.id)}"`)}</div></article>`;}).join('')}</section>${!debtList.length?`<div class="panel">${empty('التزام كبير، بخطوات أصغر','سجّل المبلغ المتبقي والقسط الشهري، وشوف تقدمك.','add-debt','إضافة التزام','debt')}</div>`:''}<div class="gentle-note">${icon('info')}موعد الانتهاء تقديري على أساس قسط ثابت، بدون فوائد إضافية. لا تضف هنا قسطاً مسجّلاً ضمن استقطاعات الراتب.</div>${state.debts.some(x=>x.archived)?`<div class="panel section-space"><h2>التزامات مؤرشفة</h2>${state.debts.filter(x=>x.archived).map(x=>`<div class="list-item"><div class="grow">${esc(x.name)}</div>${button('استعادة','restore-debt',`data-id="${esc(x.id)}"`,'secondary small-btn')}</div>`).join('')}</div>`:''}`;}
  function transactions(){const rows=state.transactions.filter(t=>J.month(t.date)===selectedMonth&&(txFilter==='all'||t.kind===txFilter)&&(`${t.name} ${t.note} ${J.categoryNames[t.category]}`).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return title('كل حركة إلها حكاية','دخل، مصروف، وتفاصيل صغيرة بتكمّل الصورة.',button(`${icon('plus')} حركة جديدة`,'add-expense'))+`<div class="panel-heading">${monthControl()}</div><div class="transaction-controls"><input id="tx-search" aria-label="بحث في الحركات" placeholder="دوّر على حركة أو ملاحظة…" value="${esc(search)}"><select id="tx-filter" aria-label="نوع الحركات"><option value="all" ${txFilter==='all'?'selected':''}>كل الحركات</option><option value="expense" ${txFilter==='expense'?'selected':''}>المصاريف</option><option value="income" ${txFilter==='income'?'selected':''}>الدخل</option></select>${button('إضافة دخل','add-income','','secondary')}</div><div class="panel">${rows.map(t=>`<div class="transaction-row"><span class="stat-symbol ${t.kind==='income'?'':'expense'}">${icon(t.kind==='income'?'down':'up')}</span><div class="grow"><h3>${esc(t.name)}</h3><div class="item-meta"><span>${formatDate(t.date)}</span><span>· ${J.categoryNames[t.category]}</span>${t.sourceType?'<span class="badge">دفعة مرتبطة</span>':''}</div>${t.note?`<p class="fine">${esc(t.note)}</p>`:''}</div><div class="item-amount ${t.kind==='income'?'positive':''}">${t.kind==='income'?'+':'−'} ${converted(t.amount,t.currency)}</div>${iButton('edit',t.sourceType?'payment-detail':'edit-transaction','تفاصيل الحركة',`data-id="${esc(t.id)}"`)}${!t.sourceType?iButton('trash','delete-transaction','حذف الحركة',`data-id="${esc(t.id)}"`):''}</div>`).join('')||empty('ما في حركات بهالشهر','جرّب شهراً آخر، أو سجّل أول حركة.','add-expense','إضافة حركة','salary')}</div>`;}
  function trendChart(){const months=Array.from({length:6},(_,i)=>J.month(J.addMonths(`${selectedMonth}-01`,i-5))),vals=months.map(m=>Object.values(J.report(state,m)).reduce((a,b)=>a+b,0)),max=Math.max(1,...vals);return `<div class="mini-chart" style="height:205px">${months.map((m,i)=>`<div class="mini-col"><b>${n(vals[i],0)}</b><div class="bar" style="height:${vals[i]/max*145}px;background:${m===selectedMonth?'var(--pine)':'#8faa84'}" role="img" aria-label="${monthName(m)}: ${n(vals[i],digits[state.settings.base])} ${units[state.settings.base]}"></div><small>${monthShort(m)}</small></div>`).join('')}</div>`;}
  function reports(){const s=J.summary(state,selectedMonth),previous=J.summary(state,J.month(J.addMonths(`${selectedMonth}-01`,-1))),diff=s.expense-previous.expense;return title('الصورة الأوسع','قرارات أهدأ، لما تشوف الأرقام بوضوح.',monthControl())+`<section class="summary-strip">${[[s.income,'الدخل المسجّل'],[s.expense,'المصروف المسجّل'],[s.income-s.expense,'فرق الدخل والمصروف']].map(([v,l])=>`<div class="summary-tile"><div class="label">${l}</div><div class="value">${money(v)}</div></div>`).join('')}</section><section class="content-two"><div class="panel"><div class="panel-heading"><div><h2>المصروف على مدى ٦ أشهر</h2><p>بالـ ${state.settings.base} حسب تاريخ الدفع الفعلي</p></div><span class="badge ${diff>0?'warn':'ok'}">${diff===0?'نفس المصروف':`${diff>0?'زيادة':'أقل'} ${money(Math.abs(diff))}`}</span></div>${trendChart()}<div class="gentle-note">${icon('info')}المقارنة مع الشهر السابق. الشهر الحالي ممكن لسه ما اكتمل.</div></div><div class="panel"><div class="panel-heading"><h2>توزيع المصاريف</h2></div>${donut(selectedMonth)}</div></section><div class="panel section-space"><h2>تفاصيل ${monthName(selectedMonth)}</h2><div class="detail-pairs" style="margin-top:20px">${Object.entries(J.report(state,selectedMonth)).map(([k,v])=>`<div><span>${J.categoryNames[k]}</span><strong>${money(v)}</strong></div>`).join('')}</div><div class="gentle-note">${icon('info')}كل الملخصات، بما فيها الأشهر الماضية، محسوبة بأسعار الصرف اليدوية الحالية. الاستقطاعات محسوبة ضمن صافي الراتب وليست مصروفاً ثانياً.</div></div>`;}
  function settings(){const st=state.settings;return title('جيبتك، على طريقتك','العملة، التذكير، ونسخة أمان لبياناتك.')+`<section class="settings-grid">${syncPanel()}<div class="panel setting-block"><h2>العملة وأسعار الصرف</h2><p>سعر كل وحدة بالـ JOD. التحويل بين العملات الثلاثة تلقائي.</p><form id="settings-form"><div class="form-grid">${selectField('base','العملة الأساسية',J.currencies.map(c=>[c,`${c} · ${{JOD:'دينار أردني',USD:'دولار أمريكي',IQD:'دينار عراقي'}[c]}`]),st.base,'full')}${field('usd','١ دولار أمريكي = كم دينار أردني؟',st.rates.USD,'number','min="0.000000001" step="any" required','full')}${field('iqd','١ دينار عراقي = كم دينار أردني؟',st.rates.IQD,'number','min="0.000000001" step="any" required','full')}</div><p class="fine" style="margin-top:15px">${st.ratesConfirmed?`آخر تحديث يدوي: ${st.ratesDate?formatDate(st.ratesDate,true):'غير محدد'}`:'القيم الحالية توضيحية وليست أسعاراً مباشرة. راجعها وأكّدها قبل الاعتماد على التحويل.'}</p><p class="fine">١ JOD = ${n(1/st.rates.USD,4)} USD · ${n(1/st.rates.IQD,2)} IQD</p><div class="field-error" role="alert"></div><div class="form-actions"><button class="btn" type="submit">حفظ وتأكيد أسعار الصرف</button></div></form></div><div class="panel setting-block"><h2>المظهر والتذكيرات</h2><p>إعدادات صغيرة بتناسب يومك.</p><div class="settings-list"><div class="row"><div class="grow"><h3>المظهر</h3></div><select id="theme-select" style="max-width:165px" aria-label="مظهر التطبيق">${[['system','حسب الجهاز'],['light','فاتح'],['dark','داكن']].map(([v,l])=>`<option value="${v}" ${st.theme===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="row"><div class="grow"><h3>التذكيرات داخل التطبيق</h3><p>تتحدث عند الفتح، للأقرب حسب تذكير كل بند.</p></div><input type="checkbox" class="switch" id="notifications-toggle" aria-label="التذكيرات داخل التطبيق" ${st.notifications?'checked':''}></div><div class="row"><div class="grow"><h3>التذكير الافتراضي</h3><p>للإضافات الجديدة</p></div><select id="reminder-select" aria-label="أيام التذكير الافتراضي" style="max-width:115px">${[0,1,2,3,5,7,14,30,...(![0,1,2,3,5,7,14,30].includes(st.reminderDays)?[st.reminderDays]:[])].sort((a,b)=>a-b).map(d=>`<option value="${d}" ${st.reminderDays===d?'selected':''}>${d===0?'نفس اليوم':`${d} أيام`}</option>`).join('')}</select></div></div><div class="form-actions">${button('السماح بشارة الأيقونة','badge','','secondary')}${button('تصدير للتقويم','calendar','','secondary')}</div><div class="gentle-note">${icon('bell')}بدون خدمة خارجية، ما في تنبيه مضمون والتطبيق مغلق. الشارة تتحدث عند الفتح إذا سمح جهازك. ملف التقويم ينقل المواعيد للتطبيق الذي تختاره؛ راجع تنبيهاته بعد الاستيراد.</div></div><div class="panel setting-block"><h2>نسخة أمان وخصوصية</h2><p>البيانات على هالجهاز. خذ نسخة قبل تغيير الجهاز أو مسح المتصفح.</p><div class="row wrap">${button(`${icon('download')} تصدير JSON`,'export','','secondary')}${button(`${icon('upload')} استيراد نسخة`,'import','','secondary')}</div><input type="file" id="import-file" accept=".json,application/json" hidden><div class="settings-list section-space"><div class="row"><div class="grow"><h3>قفل برمز PIN</h3><p>${st.pin?'مفعّل عند الفتح والعودة للتطبيق':'قفل بسيط للشاشة، وليس تشفيراً للبيانات'}</p></div>${button(st.pin?'تغيير الرمز':'تفعيل','pin','','secondary small-btn')}${st.pin?iButton('close','remove-pin','تعطيل القفل'):''}</div><div class="row"><div class="grow"><h3>رصيد البداية</h3><p>${money(st.openingAmount,st.openingCurrency)} · ${formatDate(st.openingDate)}</p></div>${button('تعديل','setup','','secondary small-btn')}</div></div><p class="fine" style="margin-top:13px">نسخة JSON غير مشفّرة ولا تحتوي رمز القفل؛ احفظها بمكان آمن. قفل الشاشة لا يغني عن قفل جهازك.</p><div class="form-actions">${button('طلب حفظ دائم للجهاز','persist','','secondary')}</div>${broken?`<div class="gentle-note">تعذر قراءة البيانات الحالية. نزّل الملف المتضرر قبل أي مسح. ${button('تنزيل الملف الأصلي','export-raw','','secondary')}</div>`:''}</div><div class="panel setting-block"><h2>خلي جيبتك على الشاشة الرئيسية</h2><p>على آيفون، افتح الرابط باستخدام Safari.</p><ol class="install-steps"><li>اضغط زر <strong>المشاركة</strong>.</li><li>اختر <strong>إضافة إلى الشاشة الرئيسية</strong>.</li><li>اترك <strong>فتح كتطبيق ويب</strong> مفعّلاً إذا ظهر.</li><li>اضغط <strong>إضافة</strong>، وافتح جيبتك من أيقونته.</li></ol><div class="gentle-note">${icon('info')}العمل بدون إنترنت متاح بعد أول تحميل ناجح عبر HTTPS. ملف HTML المحلي يشغّل الواجهة، لكن تثبيت PWA يحتاج رابطاً آمناً.</div><p id="offline-status" class="fine" style="margin-top:15px">${location.protocol==='file:'?'أنت تفتح ملفاً محلياً. استخدم رابط HTTPS للتثبيت.':navigator.serviceWorker?.controller?'جيبتك محفوظ للعمل بدون إنترنت.':'جارٍ تجهيز نسخة العمل بدون إنترنت…'}</p></div></section><div class="panel section-space"><div class="row between wrap"><div><h3>بداية جديدة</h3><p class="fine">المسح نهائي لهذا الجهاز. صدّر نسخة أولاً.</p></div>${button('مسح كل البيانات','clear','','danger')}</div></div>`;}
  function notifications(){const all=J.occurrences(state,J.addDays(J.today(),90)),reminded=all.filter(o=>J.dayDiff(o.date)<=o.reminder);return title('نلحقها قبل موعدها','التنبيهات حسب التذكير الخاص بكل فاتورة واشتراك.',button(`${icon('calendar')} للتقويم`,'calendar','','secondary'))+`${!state.settings.notifications?'<div class="banner warning">التذكيرات معطّلة من الإعدادات. قائمة الاستحقاقات بتظل متاحة هون.</div>':''}<div class="panel"><div class="panel-heading"><h2>تحتاج انتباهك</h2><span class="badge warn">${reminded.length}</span></div>${reminded.length?`<div class="row between wrap bulk-settle-bar"><label class="fine"><input type="checkbox" id="settle-all"> تحديد الكل</label>${button('اعتبر المحدّد مسدّداً','settle-picked','','secondary small-btn')}</div>${upcomingItems(reminded,1000,true,true)}<p class="fine">«اعتبر المحدّد مسدّداً» بيعلّمهم كمدفوعين بدون تسجيل حركة مالية — للبنود اللي دفعتها فعلاً برّا التطبيق.</p>`:empty('كل شي تحت السيطرة','ما في استحقاقات ضمن فترة التذكير حالياً.','','','bills')}</div><div class="panel section-space"><div class="panel-heading"><h2>باقي الـ ١٤ يوم الجايين</h2></div>${upcomingItems(all.filter(x=>!reminded.includes(x)&&J.dayDiff(x.date)<=14),1000)||'<p class="fine">ما في مواعيد إضافية خلال هالفترة.</p>'}</div><div class="gentle-note">${icon('info')}إلغاء الاشتراك أو تجميده من جيبتك يسجّل قرارك فقط. لازم تلغي التجديد أيضاً من موقع الخدمة أو إعدادات اشتراكات Apple.</div>`;}
  const more=()=>title('الباقي بجيبتك','كل أدواتك، بمكان واحد.')+`<div class="more-menu">${['salary','debts','transactions','settings','notifications'].map(k=>`<a href="#${k}">${icon(k==='notifications'?'bell':k)}<span>${labels[k]}</span></a>`).join('')}<button class="quick-action" data-action="install">${icon('download')}كيف أثبّت جيبتك؟</button></div>`;
  function render(){applyTheme();if(locked){renderLock();return;}const reminders=state.settings.notifications?J.occurrences(state,J.addDays(J.today(),90)).filter(o=>J.dayDiff(o.date)<=o.reminder).length:0;const mainNav=['dashboard','subscriptions','bills','salary','debts','transactions','reports'];const mobile=['dashboard','subscriptions','bills','reports','more'];app.innerHTML=`<aside class="sidebar"><a href="#dashboard" class="brand"><img src="assets/app-icon.svg" alt=""><div><span class="brand-name">جيبتك<span>.</span></span><div class="brand-sub">مصاريك على بالِك</div></div></a><nav class="nav-list" aria-label="التنقل الرئيسي">${mainNav.map(k=>`<a href="#${k}" class="${route===k?'active':''}" ${route===k?'aria-current="page"':''}>${icon(k==='dashboard'?'home':k)}<span>${labels[k]}</span></a>`).join('')}</nav><div class="nav-label">على طريقتك</div><nav class="nav-list"><a href="#settings" class="${route==='settings'?'active':''}">${icon('settings')}الإعدادات</a></nav><div class="sidebar-bottom"><div class="privacy">${icon('shield')}<span>بياناتك إلك لحالك.<br>محفوظة على جهازك${sync?.connected()?" ومتزامنة بتشفير":""}.</span></div><span class="version">جيبتك · إصدار ١.٠</span></div></aside><div class="workspace"><header class="topbar"><a href="#dashboard" class="mobile-logo" style="text-decoration:none"><img src="assets/app-icon.svg" alt=""><span class="brand-name">جيبتك<span>.</span></span></a><div class="topbar-title">مساحتك المالية <strong>/ ${labels[route]||labels.dashboard}</strong></div><div class="topbar-tools">${button(`${icon('plus')}<span class="button-label">إضافة حركة</span>`,'add-expense','aria-label="إضافة حركة"') }<button class="icon-button" data-action="notifications" aria-label="التنبيهات، ${reminders} استحقاق">${icon('bell')}${reminders?`<span class="notification-dot">${Math.min(99,reminders)}</span>`:''}</button><button class="avatar" data-action="settings" aria-label="الإعدادات">ج</button></div></header><main id="main" class="page" tabindex="-1">${demo?`<div class="banner demo-banner">${icon('eye')}<div class="grow"><strong>وضع تجريبي — الأرقام للتوضيح</strong>أي تعديل هون ما بيغيّر بياناتك الشخصية.</div>${button('ابدأ ببياناتي','exit-demo','','secondary small-btn')}</div>`:''}${sync?.connected()&&!demo?`<div class="sync-strip"><span data-sync-status role="status">${esc(sync.message)}</span><button class="btn secondary small-btn" type="button" data-action="sync-conflict" data-sync-review ${sync.status==='conflict'?'':'hidden'}>مراجعة النسختين</button></div>`:''}${broken?'<div class="banner warning">تعذّر قراءة البيانات المحفوظة. الأصل ما زال محفوظاً؛ افتح الإعدادات للاستعادة أو التنزيل.</div>':''}${({dashboard,subscriptions,bills,salary,debts,transactions,reports,settings,notifications,more}[route]||dashboard)()}</main><footer class="footer-note">${icon('shield')}جيبتك أهدى، لما تكون الصورة أوضح.</footer></div><nav class="bottom-nav" aria-label="التنقل السفلي">${mobile.map(k=>`<a href="#${k}" class="${route===k||(k==='more'&&!mobile.includes(route))?'active':''}" ${route===k?'aria-current="page"':''}>${icon(k==='dashboard'?'home':k)}<span>${k==='dashboard'?'الرئيسية':labels[k]}</span></a>`).join('')}</nav>`;animateCounts();updateBadge();}
  function animateCounts(){if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;document.querySelectorAll('[data-count]').forEach(el=>{const value=+el.dataset.count,digits=+el.dataset.digits,start=performance.now();function tick(t){if(!el.isConnected)return;const p=Math.min(1,(t-start)/650);el.textContent=n(value*(1-Math.pow(1-p,3)),digits);if(p<1)requestAnimationFrame(tick);}requestAnimationFrame(tick);});}
  function field(name,label,value='',type='text',attrs='',cls=''){return `<div class="field ${cls}"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
  function selectField(name,label,options,value,cls=''){return `<div class="field ${cls}"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
  const currencyField=c=>selectField('currency','العملة',J.currencies.map(c=>[c,`${c} · ${units[c]}`]),c||state.settings.base);
  const amountField=(amount='',label='المبلغ')=>field('amount',label,amount,'number','min="0.000001" max="1000000000000" step="any" inputmode="decimal" required');
  const reminderField=r=>field('reminder','تذكير قبل الموعد (أيام)',r??state.settings.reminderDays,'number','min="0" max="90" step="1" required');
  function openModal(heading,body,handler=null,submit='حفظ'){lastFocus=document.activeElement;dialogAction=handler;modal.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${heading}</h2>${iButton('close','close','إغلاق النافذة')}</div>${handler?`<form id="dialog-form">${body}<div class="field-error" role="alert"></div><div class="form-actions"><button class="btn" type="submit">${submit}</button>${button('رجوع','close','','secondary')}</div></form>`:body}`;if(!modal.open)modal.showModal();document.body.style.overflow='hidden';}
  function closeModal(){modal.close();document.body.style.overflow='';dialogAction=null;lastFocus?.focus?.();}
  modal.addEventListener('close',()=>{document.body.style.overflow='';});
  function confirmAction(h,p,fn,submit='تأكيد'){openModal(h,`<p class="modal-intro">${p}</p>`,()=>{commit(fn);closeModal();render();toast('تم الحفظ');},submit);}
  function parseNumber(v){const str=String(v??'').replace(/[٠-٩]/g,c=>c.charCodeAt(0)-1632).replace(/[۰-۹]/g,c=>c.charCodeAt(0)-1776).replace(/٫/g,'.').replace(/٬/g,'');const number=Number(str);if(!str.trim()||!Number.isFinite(number))throw new Error('أدخل رقماً صحيحاً.');return number;}
  function numberIn(fd,key,min=0,max=1e12){const v=parseNumber(fd.get(key));if(v<min||v>max)throw new Error('راجع المبلغ أو العدد المُدخل.');return v;}
  const formName=fd=>{const t=String(fd.get('name')||'').trim();if(!t||t.length>100)throw new Error('أدخل اسماً بين حرف و١٠٠ حرف.');return t;};
  function saveDone(fn,msg='تم الحفظ، وكل شي محسوب'){commit(fn);closeModal();render();toast(msg);if(!demo)sync?.tick();}
  function transactionForm(id=null,kind='expense'){const x=state.transactions.find(t=>t.id===id)||{date:J.today(),currency:state.settings.base,kind,category:kind==='income'?'other':'general'};openModal(id?'تعديل الحركة':kind==='income'?'دخل جديد عَ جيبتك':'مصروف جديد',`<div class="form-grid">${field('name','اسم الحركة',x.name||'','text','required maxlength="100"','full')}${amountField(x.amount)}${currencyField(x.currency)}${selectField('kind','نوع الحركة',[['expense','مصروف'],['income','دخل']],x.kind)}${selectField('category','التصنيف',Object.entries(J.categoryNames),x.category)}${field('date','التاريخ',x.date,'date',`required max="${J.today()}"`,'full')}${field('note','ملاحظة (اختياري)',x.note||'','text','maxlength="500"','full')}</div>`,fd=>{const t={id:id||J.uid(),name:formName(fd),amount:numberIn(fd,'amount',.000001),currency:fd.get('currency'),kind:fd.get('kind'),category:fd.get('category'),date:fd.get('date'),note:String(fd.get('note')||'').trim()};saveDone(s=>{if(id)s.transactions=s.transactions.filter(t=>t.id!==id);J.record(s,t);});});}
  function subForm(id=null,resume=false){const x=state.subscriptions.find(t=>t.id===id)||{currency:state.settings.base,cycle:1,nextDate:J.addMonths(J.today(),1),lastPaid:J.today(),lastUsed:J.today(),reminder:state.settings.reminderDays,category:'ترفيه'};openModal(resume?'إعادة تفعيل الاشتراك':id?'تعديل الاشتراك':'اشتراك جديد',`<div class="form-grid">${field('name','اسم الاشتراك',x.name||'','text','required maxlength="100"','full')}${amountField(x.amount,'تكلفة كل تجديد')}${currencyField(x.currency)}${selectField('cycle','دورة الفوترة',[[1,'شهري'],[3,'كل ٣ أشهر'],[6,'كل ٦ أشهر'],[12,'سنوي']],x.cycle)}${selectField('category','الفئة',['ترفيه','عمل','رياضة','تخزين سحابي','تعليم','أخرى'].map(s=>[s,s]),x.category)}${field('lastPaid','تاريخ آخر دفعة',x.lastPaid||'','date',`max="${J.today()}"`)}${field('nextDate','التجديد القادم',resume?J.addMonths(J.today(),x.cycle):x.nextDate,'date','required')}${field('lastUsed','آخر استخدام مؤكّد',x.lastUsed,'date',`required max="${J.today()}"`)}${reminderField(x.reminder)}</div><div class="gentle-note">${icon('info')}موعد التجديد يُحسب من آخر دفعة ودورة الفوترة؛ فيك تعدّله. إدخال آخر دفعة هنا لا يسجّل حركة مالية قديمة.</div>`,fd=>{const item={...x,id:id||J.uid(),name:formName(fd),amount:numberIn(fd,'amount',.000001),currency:fd.get('currency'),cycle:numberIn(fd,'cycle',1,12),category:fd.get('category'),lastPaid:fd.get('lastPaid'),nextDate:fd.get('nextDate'),lastUsed:fd.get('lastUsed'),reminder:numberIn(fd,'reminder',0,90),status:resume?'active':x.status||'active'};if(!J.validDate(item.nextDate)||!J.validDate(item.lastUsed)||item.lastUsed>J.today()||item.lastPaid&&(!J.validDate(item.lastPaid)||item.lastPaid>J.today()))throw new Error('راجع تواريخ الاشتراك.');item.anchorDay=id&&item.nextDate===x.nextDate?x.anchorDay:(item.lastPaid&&item.nextDate===J.addMonths(item.lastPaid,item.cycle)?Number(item.lastPaid.slice(8)):Number(item.nextDate.slice(8)));if(resume){delete item.cancelledDate;delete item.cancelledNextDate;delete item.cancelledAmount;}saveDone(s=>{s.subscriptions=id?s.subscriptions.map(t=>t.id===id?item:t):[...s.subscriptions,item];});});}
  function billForm(id=null){const x=state.bills.find(t=>t.id===id)||{currency:state.settings.base,dueDay:15,startDate:J.today(),reminder:state.settings.reminderDays,archived:false};openModal(id?'تعديل الفاتورة':'فاتورة متكررة جديدة',`<div class="form-grid">${field('name','اسم الفاتورة',x.name||'','text','required maxlength="100"','full')}${amountField(x.amount,'المبلغ الشهري المتوقع')}${currencyField(x.currency)}${field('dueDay','يوم الاستحقاق من كل شهر',x.dueDay,'number','required min="1" max="31"')}${reminderField(x.reminder)}${field('startDate','تبدأ الاستحقاقات من',x.startDate,'date','required','full')}${field('settledThrough','مدفوعة حتى نهاية شهر (اختياري)',x.settledThrough||'','month',`max="${J.month()}"`,'full')}</div><div class="gentle-note">${icon('info')}«مدفوعة حتى» بتعتبر هذا الشهر وكل شهر قبله مسدّداً: ما بيطلع تنبيه ولا بدّه تأكيد، وما بتتسجّل حركة نقدية. الشهور بعده بتظهر عادي. لو الشهر أقصر من يوم الاستحقاق، بنعتمد آخر يوم فيه. تغيير المبلغ أو الاسم ما بيعدّل الدفعات الماضية.</div>`,fd=>{const item={...x,id:id||J.uid(),name:formName(fd),amount:numberIn(fd,'amount',.000001),currency:fd.get('currency'),dueDay:numberIn(fd,'dueDay',1,31),reminder:numberIn(fd,'reminder',0,90),startDate:fd.get('startDate')};const settled=String(fd.get('settledThrough')||'').trim();if(settled)item.settledThrough=settled;else delete item.settledThrough;if(!J.validDate(item.startDate))throw new Error('راجع تاريخ البداية.');if(item.settledThrough&&(!/^\d{4}-\d{2}$/.test(item.settledThrough)||item.settledThrough>J.month()))throw new Error('راجع شهر «مدفوعة حتى».');if(id&&item.currency!==x.currency&&state.transactions.some(t=>t.sourceId===id))throw new Error('لهذه الفاتورة دفعات بعملتها الأصلية. أنشئ فاتورة جديدة للعملة الأخرى.');saveDone(s=>{s.bills=id?s.bills.map(t=>t.id===id?item:t):[...s.bills,item];});});}
  function debtForm(id=null){const x=state.debts.find(t=>t.id===id)||{currency:state.settings.base,dueDay:25,startDate:J.today(),reminder:state.settings.reminderDays,archived:false};openModal(id?'تعديل الالتزام':'التزام جديد',`<div class="form-grid">${field('name','اسم الالتزام أو الشخص',x.name||'','text','required maxlength="100"','full')}${field('total','أصل القرض / المبلغ الكلي',x.total||'','number','required min="0.000001" step="any"')}${field('remaining','المبلغ المتبقي حالياً',x.remaining??'','number','required min="0" step="any"')}${field('installment','القسط الشهري',x.installment||'','number','required min="0.000001" step="any"')}${currencyField(x.currency)}${field('dueDay','يوم القسط من كل شهر',x.dueDay,'number','required min="1" max="31"')}${reminderField(x.reminder)}${field('startDate','تبدأ الدفعات من',x.startDate,'date','required','full')}${field('settledThrough','مدفوع حتى نهاية شهر (اختياري)',x.settledThrough||'','month',`max="${J.month()}"`,'full')}</div><details class="bank-details" ${x.bank?'open':''}><summary>تفاصيل القرض البنكي (اختياري)</summary><label class="check-field"><input type="checkbox" name="bankEnabled" ${x.bank?'checked':''}>اعتماد تفاصيل جدول البنك</label><div class="form-grid">${field('bankPaidPercent','نسبة السداد حسب البنك (%)',x.bank?.paidPercent??'','number','min="0" max="100" step="any"')}${field('bankEndDate','تاريخ القسط الأخير',x.bank?.endDate??'','date')}${field('bankTermMonths','مدة العقد بالأشهر',x.bank?.termMonths??'','number','min="1" max="1200" step="1"')}${field('bankApr','الفائدة السنوية / APR (%)',x.bank?.apr??'','number','min="0" max="100" step="any"')}${field('bankInterest','مجموع الفوائد',x.bank?.interest??'','number','min="0" step="any"')}${field('bankFees','العمولات والرسوم',x.bank?.fees??'','number','min="0" step="any"')}${field('bankLastInstallment','مبلغ القسط الأخير',x.bank?.lastInstallment??'','number','min="0.000001" step="any"')}</div><p class="fine">انسخ تفاصيل البنك كما هي. لا نشتق نسبة البنك من المتبقي، ولا نضيف الفوائد إلى أصل القرض.</p></details><div class="gentle-note">${icon('info')}«مدفوع حتى» بتخلي الجدول يبدأ من الشهر اللي بعده، وبتعتبر «المبلغ المتبقي» أعلاه هو الرصيد الحالي. تعديل المتبقي هو تصحيح مباشر للتخطيط، وليس حركة نقدية. لتسجيل سداد استخدم «تسجيل قسط».</div>`,fd=>{const item={...x,id:id||J.uid(),name:formName(fd),total:numberIn(fd,'total',.000001),remaining:numberIn(fd,'remaining'),installment:numberIn(fd,'installment',.000001),currency:fd.get('currency'),dueDay:numberIn(fd,'dueDay',1,31),startDate:fd.get('startDate'),reminder:numberIn(fd,'reminder',0,90)};const settled=String(fd.get('settledThrough')||'').trim();if(settled)item.settledThrough=settled;else delete item.settledThrough;if(fd.has('bankEnabled')){item.bank={paidPercent:numberIn(fd,'bankPaidPercent',0,100),endDate:fd.get('bankEndDate'),termMonths:numberIn(fd,'bankTermMonths',1,1200),apr:numberIn(fd,'bankApr',0,100),interest:numberIn(fd,'bankInterest'),fees:numberIn(fd,'bankFees'),lastInstallment:numberIn(fd,'bankLastInstallment',.000001)};if(!J.validDate(item.bank.endDate)||item.bank.endDate<item.startDate||!Number.isInteger(item.bank.termMonths))throw new Error('راجع تاريخ نهاية العقد ومدته.');}else delete item.bank;if(item.remaining>item.total)throw new Error('المتبقي لا يمكن أن يكون أكبر من المبلغ الكلي.');if(!J.validDate(item.startDate))throw new Error('راجع تاريخ البداية.');if(item.settledThrough&&(!/^\d{4}-\d{2}$/.test(item.settledThrough)||item.settledThrough>J.month()))throw new Error('راجع شهر «مدفوع حتى».');if(id&&item.currency!==x.currency&&state.transactions.some(t=>t.sourceId===id))throw new Error('لهذا الالتزام دفعات. أنشئ التزاماً جديداً لتغيير العملة.');saveDone(s=>{s.debts=id?s.debts.map(t=>t.id===id?item:t):[...s.debts,item];});});}
  function payForm(type,id,period){const x=state[type].find(x=>x.id===id);if(!x)return;const due=type==='subscriptions'?period:type==='debts'&&x.bank&&period===J.month(x.bank.endDate)?x.bank.endDate:J.dueInMonth(period,x.dueDay),o={type,id,period,date:due,name:x.name,currency:x.currency,amount:type==='debts'?(J.occurrences(state,due).find(y=>y.type===type&&y.id===id&&y.period===period)?.amount??Math.min(x.installment,x.remaining)):x.amount};openModal(type==='subscriptions'?'جدّد وسجّل الدفعة':'تسجيل دفعة',`<p class="modal-intro">${esc(x.name)} · استحقاق ${formatDate(due,true)}</p><div class="form-grid">${amountField(o.amount,`المبلغ الفعلي (${x.currency})`)}${field('paidDate','تاريخ الدفع',J.today(),'date',`required max="${J.today()}"`)}${type==='debts'&&x.bank?field('remainingAfter','الرصيد المتبقي بعد القسط حسب كشف البنك','','number',`required min="0" max="${x.remaining}" step="any"`,'full'):''}</div>${type==='subscriptions'?'<div class="gentle-note">هذا تسجيل للدفعة؛ ما بنسحب مصاري ولا بنجدّد لدى الخدمة. الموعد القادم يتقدّم دورة واحدة من تاريخ استحقاقه.</div>':''}`,fd=>saveDone(s=>J.pay(s,o,numberIn(fd,'amount',.000001),fd.get('paidDate'),type==='debts'&&x.bank?numberIn(fd,'remainingAfter'):undefined),'تم تسجيل الدفعة وتحديث جيبتك'),'تأكيد تسجيل الدفع');}
  function billHistory(id){const x=state.bills.find(t=>t.id===id),tx=state.transactions.filter(t=>t.sourceType==='bills'&&t.sourceId===id).sort((a,b)=>a.period.localeCompare(b.period));const latest=tx.slice(-6),max=Math.max(1,...latest.map(t=>t.amount));openModal(`سجل ${esc(x.name)}`,tx.length?`<div class="mini-chart">${latest.map(t=>`<div class="mini-col"><b>${n(t.amount,digits[t.currency])}</b><div class="bar" style="height:${t.amount/max*90}px"></div><small>${monthShort(t.period)}</small></div>`).join('')}</div><div class="rule"></div>${tx.slice().reverse().map(t=>`<div class="list-item"><div class="grow"><div class="item-name">${monthName(t.period)}</div><div class="fine">دُفعت ${formatDate(t.date,true)}</div></div><div>${money(t.amount,t.currency)}</div>${iButton('edit','payment-detail','تفاصيل الدفعة',`data-id="${esc(t.id)}"`)}</div>`).join('')}`:empty('لسه ما في دفعات','سجّل أول دفعة فعلية لتبدأ المقارنة بين الشهور.','','','bills'));}
  function setup(){const st=state.settings;openModal('رصيد البداية',`<p class="modal-intro">كم كان معك في بداية هذا التاريخ؟ الحركات المسجّلة من هذا التاريخ تُضاف وتُخصم فوقه.</p><div class="form-grid">${field('amount','رصيد البداية',st.openingAmount,'number','required step="any"')}${currencyField(st.openingCurrency)}${field('openingDate','تاريخ رصيد البداية',st.openingDate,'date',`required max="${J.today()}"`,'full')}</div>`,fd=>{const d=fd.get('openingDate');if(!J.validDate(d)||d>J.today())throw new Error('راجع تاريخ البداية.');saveDone(s=>{s.settings.openingAmount=numberIn(fd,'amount',-1e12);s.settings.openingCurrency=fd.get('currency');s.settings.openingDate=d;});if(!state.salary.amount){location.hash='salary';toast('الرصيد جاهز. أضف راتبك من تعديل الراتب.');}});}
  function salaryForm(){const x=state.salary;openModal('الراتب الشهري',`<div class="form-grid">${field('amount','الراتب الإجمالي',x.amount,'number','required min="0" step="any"')}${currencyField(x.currency)}${field('payDay','يوم استلام الراتب',x.payDay,'number','required min="1" max="31"','full')}</div><div class="gentle-note">الاستقطاعات بنفس عملة الراتب. التعديل يغيّر التخطيط المقبل؛ الرواتب المستلمة تبقى بقيمتها المسجّلة.</div>`,fd=>{const amount=numberIn(fd,'amount'),currency=fd.get('currency');if(x.deductions.filter(d=>d.recurring||d.month===J.month()).reduce((a,d)=>a+d.amount,0)>amount)throw new Error('الراتب أقل من الاستقطاعات الحالية. عدّل الاستقطاعات أولاً.');if(currency!==x.currency&&x.deductions.length)throw new Error('عدّل أو احذف الاستقطاعات أولاً قبل تغيير عملة الراتب.');saveDone(s=>Object.assign(s.salary,{amount,currency,payDay:numberIn(fd,'payDay',1,31)}));});}
  function deductionForm(id=null){const x=state.salary.deductions.find(x=>x.id===id)||{amount:'',recurring:true,month:selectedMonth};openModal(id?'تعديل الاستقطاع':'استقطاع جديد',`<div class="form-grid">${field('name','اسم الاستقطاع',x.name||'','text','required maxlength="100"','full')}${amountField(x.amount,`المبلغ (${state.salary.currency})`)}${field('month','شهر الاستقطاع',x.month,'month','required')}<label class="check-field field full"><input name="recurring" type="checkbox" ${x.recurring?'checked':''}>يتكرر تلقائياً في حساب كل راتب</label></div>`,fd=>{const item={id:id||J.uid(),name:formName(fd),amount:numberIn(fd,'amount',.000001),month:fd.get('month'),recurring:fd.has('recurring')};if(!/^\d{4}-\d{2}$/.test(item.month))throw new Error('اختر شهراً صحيحاً.');const others=state.salary.deductions.filter(d=>d.id!==id&&(d.recurring||d.month===item.month)).reduce((a,d)=>a+d.amount,0);if(others+item.amount>state.salary.amount)throw new Error('الاستقطاعات أكبر من الراتب. عدّل الراتب أولاً.');saveDone(s=>{s.salary.deductions=id?s.salary.deductions.map(d=>d.id===id?item:d):[...s.salary.deductions,item];});});}
  async function hashPin(pin,salt){const enc=new TextEncoder(),key=await crypto.subtle.importKey('raw',enc.encode(pin),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations:150000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(b=>b.toString(16).padStart(2,'0')).join('');}
  function pinForm(){if(!crypto.subtle){toast('قفل PIN يحتاج رابط HTTPS آمناً.');return;}openModal('قفل جيبتك',`<p class="modal-intro">من ٤ إلى ٨ أرقام. القفل يحمي واجهة التطبيق، والبيانات نفسها تبقى غير مشفّرة على الجهاز.</p><div class="form-grid">${field('pin','الرمز الجديد','','password','inputmode="numeric" pattern="[0-9]{4,8}" minlength="4" maxlength="8" required autocomplete="new-password"','full')}${field('confirm','تأكيد الرمز','','password','inputmode="numeric" minlength="4" maxlength="8" required autocomplete="new-password"','full')}</div><p class="fine" style="margin-top:12px">إذا نسيت الرمز، بتحتاج مسح بيانات الموقع واستعادة نسخة JSON. صدّر نسخة قبل التفعيل.</p>`,async fd=>{const pin=fd.get('pin');if(!/^[0-9]{4,8}$/.test(pin)||pin!==fd.get('confirm'))throw new Error('الرمزان لازم يتطابقوا، من ٤ إلى ٨ أرقام.');const salt=[...crypto.getRandomValues(new Uint8Array(16))].map(b=>b.toString(16).padStart(2,'0')).join(''),hash=await hashPin(pin,salt);saveDone(s=>{s.settings.pin={salt,hash};},'تم تفعيل قفل جيبتك');});}
  function renderLock(){app.innerHTML=`<main class="lock-page"><div class="lock-card"><img src="assets/wallet-hero.svg" alt=""><h1>جيبتك إلك لحالك</h1><p>أدخل رمزك لنكمّل من وين وقفنا.</p><form id="unlock-form"><label class="hidden" for="unlock-pin">رمز PIN</label><input id="unlock-pin" type="password" inputmode="numeric" pattern="[0-9]{4,8}" maxlength="8" required autocomplete="current-password" aria-label="رمز PIN"><div class="field-error" role="alert"></div><button type="submit" class="btn">${icon('lock')} افتح جيبتك</button></form><small>نسيت الرمز؟ تحتاج نسخة JSON لاستعادة بياناتك بعد مسح بيانات الموقع. لا يوجد رمز خلفي.</small></div></main>`;}
  async function unlock(form){let guard;try{guard=JSON.parse(sessionStorage.getItem('jeebtak.pin-attempts')||'{"count":0,"until":0}');}catch{guard={count:0,until:0};}if(Date.now()<guard.until)throw new Error(`جرّب بعد ${Math.ceil((guard.until-Date.now())/1000)} ثانية.`);const pin=$('#unlock-pin').value,hash=await hashPin(pin,state.settings.pin.salt);if(hash!==state.settings.pin.hash){guard.count++;guard.until=Date.now()+(guard.count>=5?Math.min(300000,30000*2**(guard.count-5)):0);try{sessionStorage.setItem('jeebtak.pin-attempts',JSON.stringify(guard));}catch{}throw new Error('الرمز غير صحيح. جرّب مرة ثانية.');}try{sessionStorage.removeItem('jeebtak.pin-attempts');}catch{}locked=false;render();}
  function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
  function exportData(){const copy=JSON.parse(JSON.stringify(state));copy.settings.pin=null;download(JSON.stringify(copy,null,2),`jeebtak-${demo?'demo-':''}${J.today()}.json`,'application/json');toast('تم تجهيز النسخة الاحتياطية للتنزيل');}
  function calendarExport(){const events=J.occurrences(state,J.addDays(J.today(),90)).filter(o=>o.date>=J.today());if(!events.length){toast('ما في استحقاقات قادمة لتصديرها.');return;}const icsEscape=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Jeebtak//Local reminders//AR','CALSCALE:GREGORIAN',...events.flatMap(o=>['BEGIN:VEVENT',`UID:${o.type}-${o.id.replace(/[^a-zA-Z0-9-]/g,'')}-${o.period}@jeebtak.local`,`DTSTAMP:${stamp}`,`DTSTART;VALUE=DATE:${o.date.replace(/-/g,'')}`,`DTEND;VALUE=DATE:${J.addDays(o.date,1).replace(/-/g,'')}`,`SUMMARY:${icsEscape(`جيبتك: ${o.name}`)}`,`DESCRIPTION:${icsEscape(`${n(o.amount,digits[o.currency])} ${o.currency} — راجع حالة الدفع في جيبتك. المواعيد المصدّرة لا تتحدث تلقائياً.`)}`,'BEGIN:VALARM',`TRIGGER:-P${o.reminder}D`,'ACTION:DISPLAY',`DESCRIPTION:${icsEscape(o.name)}`,'END:VALARM','END:VEVENT']),'END:VCALENDAR'];const folded=lines.map(line=>{let out='',bytes=0;for(const ch of line){const count=new TextEncoder().encode(ch).length;if(bytes+count>73){out+='\r\n ';bytes=1;}out+=ch;bytes+=count;}return out;});download(folded.join('\r\n')+'\r\n',`jeebtak-reminders-${J.today()}.ics`,'text/calendar;charset=utf-8');toast('تم تصدير مواعيد ٩٠ يوم. استوردها وراجع تنبيهاتها في تقويمك.');}
  async function updateBadge(){if(!('setAppBadge' in navigator)||demo)return;const count=state.settings.notifications?J.occurrences(state,J.addDays(J.today(),90)).filter(o=>J.dayDiff(o.date)<=o.reminder).length:0;try{if(count)await navigator.setAppBadge(count);else await navigator.clearAppBadge();}catch{}}
  function paymentDetail(id){const t=state.transactions.find(x=>x.id===id);openModal('تفاصيل الدفعة',`<div class="detail-pairs"><div><span>البند</span><strong>${esc(t.name)}</strong></div><div><span>المبلغ الأصلي</span><strong>${money(t.amount,t.currency)}</strong></div><div><span>تاريخ الدفع</span><span>${formatDate(t.date,true)}</span></div><div><span>فترة الاستحقاق</span><bdi>${esc(t.period)}</bdi></div></div><div class="gentle-note">${icon('info')}للتصحيح، يمكن التراجع عن هذه الدفعة ثم تسجيلها بالقيمة الصحيحة. تجديد الاشتراك يُلغى فقط إذا كان آخر تجديد مسجّل له.</div><div class="form-actions">${button('التراجع عن الدفعة','undo-payment',`data-id="${esc(id)}"`,'danger')}</div>`);}
  function undoPayment(id){const t=state.transactions.find(x=>x.id===id);confirmAction('التراجع عن الدفعة؟','سيُعاد المبلغ إلى الرصيد، وتُعاد حالة الاستحقاق إلى غير مدفوع.',s=>{const x=s[t.sourceType]?.find(x=>x.id===t.sourceId);if(t.sourceType==='subscriptions'){if(!x||x.nextDate!==J.addMonths(t.period,x.cycle,x.anchorDay))throw new Error('تراجع عن أحدث تجديد أولاً. تعديل دورة الاشتراك قد يمنع التراجع عن دفعة قديمة.');x.nextDate=t.period;const others=s.transactions.filter(y=>y.id!==id&&y.sourceId===t.sourceId).sort((a,b)=>b.period.localeCompare(a.period));x.lastPaid=others[0]?.date||'';}if(t.sourceType==='debts'&&x){if(x.remaining+(t.debtReduction??t.amount)>x.total)throw new Error('تم تعديل رصيد الالتزام بعد هذه الدفعة. راجع المتبقي أولاً.');x.remaining=J.round(x.remaining+(t.debtReduction??t.amount));}s.transactions=s.transactions.filter(y=>y.id!==id);},'تأكيد التراجع');}
  const actions={
    'sync-pair':pairForm,'sync-now':()=>sync?.tick(),'sync-conflict':conflictForm,
    'sync-code':()=>{if(demo)throw Error('اخرج من الوضع التجريبي أولاً.');openModal('ربط جهاز آخر',`<p class="modal-intro">افتح جيبتك من أيقونته على الجهاز الآخر، ثم الإعدادات ← ربط بالمحفظة الخاصة. انسخ الرمز كاملاً والصقه هناك. الرمز يمنح الوصول الكامل لمحفظتك.</p><label class="field full">رمز الربط الخاص<textarea dir="ltr" rows="5" readonly autocomplete="off" spellcheck="false">${esc(sync.code())}</textarea></label>`);},
    'sync-disconnect':()=>{if(demo)throw Error('اخرج من الوضع التجريبي أولاً.');openModal('فصل هذا الجهاز؟','<p class="modal-intro">تبقى بياناتك على الجهاز وفي السحابة، وتتوقف المزامنة هنا. تأكد من وصول آخر تغييراتك قبل الفصل.</p>',()=>{sync.disconnect();closeModal();render();},'فصل الجهاز');},
    'sync-copies':()=>{const c=sync?.conflict;if(c){const restore=s=>({...s,settings:{...s.settings,pin:null,theme:'system'},updatedAt:new Date().toISOString()});download(JSON.stringify(restore(c.local),null,2),'jeebtak-local-copy.json','application/json');download(JSON.stringify(restore(c.remote),null,2),'jeebtak-cloud-copy.json','application/json');}},
    'sync-recovery':()=>download(localStorage.getItem('jeebtak.sync.recovery.v1')||'{}','jeebtak-sync-recovery.json','application/json'),

    'close':closeModal,'setup':setup,'add-expense':()=>transactionForm(),'add-income':()=>transactionForm(null,'income'),'edit-transaction':b=>transactionForm(b.dataset.id),'add-sub':()=>subForm(),'edit-sub':b=>subForm(b.dataset.id),'resume-sub':b=>subForm(b.dataset.id,true),'add-bill':()=>billForm(),'edit-bill':b=>billForm(b.dataset.id),'add-debt':()=>debtForm(),'edit-debt':b=>debtForm(b.dataset.id),'edit-salary':salaryForm,'add-deduction':()=>deductionForm(),'edit-deduction':b=>deductionForm(b.dataset.id),'bill-history':b=>billHistory(b.dataset.id),'pay':b=>payForm(b.dataset.type,b.dataset.id,b.dataset.period),'payment-detail':b=>paymentDetail(b.dataset.id),'undo-payment':b=>undoPayment(b.dataset.id),
    'settle-picked':()=>{const picks=new Set([...document.querySelectorAll('.settle-pick:checked')].map(el=>el.value));if(!picks.size)return toast('حدّد بند أو أكثر أولاً');const occ=J.occurrences(state,J.addDays(J.today(),90)).filter(o=>picks.has(`${o.type}:${o.id}:${o.period}`));if(!occ.length)return toast('حدّد بند أو أكثر أولاً');const items=[...new Set(occ.map(o=>o.name))];confirmAction('اعتبار المحدّد مسدّداً',`${occ.length} استحقاق (${items.join('، ')}) رح يتعلّم كمسدّد بدون تسجيل أي حركة مالية. الرصيد والتقارير ما بيتغيّروا.`,s=>J.settleOccurrences(s,occ),'اعتبرها مسدّدة');},
    'sub-filter':b=>{subFilter=b.dataset.filter;render();},'used':b=>{commit(s=>{s.subscriptions.find(x=>x.id===b.dataset.id).lastUsed=J.today();});render();toast('تم تأكيد الاستخدام اليوم');},
    'pause-sub':b=>confirmAction('تجميد الاشتراك؟','سيتوقف احتسابه ضمن الاستحقاقات. جمّده أيضاً عند مزوّد الخدمة حتى يتوقف الخصم.',s=>{s.subscriptions.find(x=>x.id===b.dataset.id).status='paused';},'تجميد'),
    'cancel-sub':b=>confirmAction('خلص، ما عاد يلزمك؟','بننقل الاشتراك للملغيات ونحسب التجديدات التي تجنّبتها. ألغِه أيضاً من موقع الخدمة أو اشتراكات Apple؛ جيبتك لا يتصل بمزوّد الخدمة.',s=>J.cancelSubscription(s,b.dataset.id),'تسجيل الإلغاء'),
    'archive-bill':b=>confirmAction('أرشفة الفاتورة؟','ستتوقف الاستحقاقات والتذكيرات، ويبقى السجل محفوظاً.',s=>{s.bills.find(x=>x.id===b.dataset.id).archived=true;},'أرشفة'),
    'archive-debt':b=>confirmAction('أرشفة الالتزام؟','ستتوقف تذكيراته وحجز أقساطه، ويبقى سجل الدفعات.',s=>{s.debts.find(x=>x.id===b.dataset.id).archived=true;},'أرشفة'),
    'restore-bill':b=>{commit(s=>{s.bills.find(x=>x.id===b.dataset.id).archived=false;});render();},'restore-debt':b=>{commit(s=>{s.debts.find(x=>x.id===b.dataset.id).archived=false;});render();},
    'delete-deduction':b=>confirmAction('حذف الاستقطاع؟','يتوقف احتسابه في التخطيط. الرواتب المستلمة لن تتغيّر.',s=>{s.salary.deductions=s.salary.deductions.filter(x=>x.id!==b.dataset.id);},'حذف'),
    'delete-transaction':b=>confirmAction('حذف الحركة؟','سيُصحح الرصيد والتقرير بعد الحذف.',s=>{s.transactions=s.transactions.filter(x=>x.id!==b.dataset.id);},'حذف'),
    'receive-salary':()=>openModal('تسجيل استلام الراتب',`<p class="modal-intro">صافي راتب ${monthName(selectedMonth)}: ${money(J.netSalary(state,selectedMonth),state.salary.currency)}</p>${field('paidDate','تاريخ الاستلام',J.today(),'date',`required max="${J.today()}"`)}`,fd=>saveDone(s=>J.receiveSalary(s,selectedMonth,fd.get('paidDate')),'وصل الراتب، وتم تحديث الرصيد'),'تأكيد الاستلام'),
    'prev-month':()=>{selectedMonth=J.month(J.addMonths(`${selectedMonth}-01`,-1));render();},'next-month':()=>{const next=J.month(J.addMonths(`${selectedMonth}-01`,1));if(next<=J.month()){selectedMonth=next;render();}},
    'notifications':()=>{location.hash='notifications';},'settings':()=>{location.hash='settings';},'install':()=>{location.hash='settings';setTimeout(()=>$('#offline-status')?.scrollIntoView({block:'center',behavior:'smooth'}),100);},
    'demo':()=>{if(state.settings.pin){toast('اخرج من قفل البيانات أولاً.');return;}demo=true;state=J.demo();render();toast('جرّب بحرية. بياناتك الحقيقية محفوظة.');},'exit-demo':()=>{demo=false;state=J.empty();load();location.hash='dashboard';render();},
    'export':exportData,'export-raw':()=>download(lastRaw||'{}',`jeebtak-recovery-${J.today()}.json`,'application/json'),'import':()=>{if(sync?.connected()&&!demo)throw Error('افصل المزامنة على هذا الجهاز قبل استيراد نسخة، ثم أعد الربط وراجع النسختين.');$('#import-file')?.click();},'calendar':calendarExport,'pin':pinForm,
    'remove-pin':()=>confirmAction('تعطيل قفل جيبتك؟','التطبيق سيفتح مباشرة بدون رمز.',s=>{s.settings.pin=null;},'تعطيل'),
    'clear':()=>openModal('مسح كل بيانات جيبتك',`<p class="modal-intro">هذه الخطوة نهائية على هذا الجهاز. صدّر نسخة JSON أولاً إذا بدك ترجع لها.</p>${field('confirmation','اكتب «مسح» للتأكيد','','text','required autocomplete="off"','full')}`,fd=>{if(!demo&&sync?.connected())throw Error('افصل هذا الجهاز عن المزامنة قبل المسح، حتى لا تعود البيانات تلقائياً.');if(fd.get('confirmation')!=='مسح')throw new Error('اكتب كلمة مسح للتأكيد.');if(!demo){localStorage.removeItem(KEY);localStorage.removeItem('jeebtak.sync.recovery.v1');lastRaw=null;}state=J.empty();broken=false;locked=false;closeModal();location.hash='dashboard';render();toast('تم مسح البيانات');},'مسح نهائي'),
    'badge':async()=>{if(!('Notification' in window)||!('setAppBadge' in navigator)){toast('شارة الأيقونة غير مدعومة هنا. جرّب من التطبيق المثبّت على آيفون.');return;}const p=await Notification.requestPermission();if(p==='granted'){await updateBadge();toast('تم السماح. الشارة تتحدث عند فتح جيبتك.');}else toast('لم يتم السماح. الاستحقاقات تبقى ظاهرة داخل التطبيق.');},
    'persist':async()=>{const ok=await navigator.storage?.persist?.();toast(ok?'تم السماح بحفظ دائم. احتفظ بنسخة أمان أيضاً.':'الجهاز لم يمنح حفظاً دائماً. صدّر نسخة JSON بانتظام.');}
  };
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;try{await actions[b.dataset.action]?.(b);}catch(err){if(modal.open){const el=modal.querySelector('.field-error');if(el)el.textContent=err.message;else toast(err.message);}else toast(err.message);}});
  document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,btn=form.querySelector('[type=submit]'),error=form.querySelector('.field-error');if(btn?.disabled)return;if(btn)btn.disabled=true;if(error)error.textContent='';try{const fd=new FormData(form);if(form.id==='dialog-form')await dialogAction?.(fd);if(form.id==='unlock-form')await unlock(form);if(form.id==='settings-form'){const usd=numberIn(fd,'usd',1e-9,1e12),iqd=numberIn(fd,'iqd',1e-9,1e12);commit(s=>{Object.assign(s.settings,{base:fd.get('base'),rates:{JOD:1,USD:usd,IQD:iqd},ratesConfirmed:true,ratesDate:J.today()});});render();toast('تم حفظ العملة وأسعار الصرف');}}catch(err){if(error){error.textContent=err.message;error.setAttribute('tabindex','-1');error.focus();}else toast(err.message);}finally{if(btn)btn.disabled=false;}});
  document.addEventListener('change',async e=>{const t=e.target;try{if(t.id==='settle-all'){document.querySelectorAll('.settle-pick').forEach(c=>{c.checked=t.checked;});return;}if(t.id==='theme-select'){commit(s=>{s.settings.theme=t.value;});render();}if(t.id==='notifications-toggle'){commit(s=>{s.settings.notifications=t.checked;});render();}if(t.id==='reminder-select'){commit(s=>{s.settings.reminderDays=+t.value;});}if(t.id==='month-select'){if(!/^\d{4}-\d{2}$/.test(t.value)||t.value>J.month())return;selectedMonth=t.value;render();}if(t.id==='tx-filter'){txFilter=t.value;render();}if(modal.open&&['f-lastPaid','f-cycle'].includes(t.id)&&$('#f-nextDate')&&$('#f-lastPaid')?.value){$('#f-nextDate').value=J.addMonths($('#f-lastPaid').value,+$('#f-cycle').value);}if(t.id==='import-file'&&t.files[0]){if(sync?.connected()&&!demo)throw Error('افصل المزامنة قبل الاستيراد.');if(t.files[0].size>15*1024*1024)throw new Error('النسخة أكبر من ١٥ ميغابايت.');let raw;try{raw=JSON.parse(await t.files[0].text());}catch{throw new Error('الملف ليس JSON صالحاً. بياناتك لم تتغيّر.');}importCandidate=J.validate(raw);openModal('استعادة النسخة الاحتياطية',`<p class="modal-intro">النسخة تحتوي ${importCandidate.transactions.length} حركة، ${importCandidate.subscriptions.length} اشتراك و${importCandidate.bills.length} فاتورة. الاستيراد يستبدل البيانات الحالية ولا يدمجها. سيتم تعطيل PIN.</p>`,()=>{if(sync?.connected()&&!demo)throw Error('افصل المزامنة قبل الاستيراد.');const next=importCandidate;next.updatedAt=new Date().toISOString();if(!demo){const raw=JSON.stringify(next);localStorage.setItem(KEY,raw);lastRaw=raw;}state=next;broken=false;locked=false;importCandidate=null;closeModal();render();toast('تمت استعادة النسخة بنجاح');},'استبدال البيانات واستعادة النسخة');t.value='';}}catch(err){toast(err.message);}});
  let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='tx-search'){const value=e.target.value,pos=e.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{search=value;render();const input=$('#tx-search');input?.focus();input?.setSelectionRange(pos,pos);},250);}});
  function setRoute(){const candidate=location.hash.slice(1)||'dashboard';route=Object.hasOwn(labels,candidate)?candidate:'dashboard';if(modal.open)closeModal();render();window.scrollTo({top:0,behavior:'instant'});}
  window.addEventListener('hashchange',setRoute);
  window.addEventListener('storage',e=>{if((e.key===KEY||e.key===null)&&!demo){load();if(modal.open)closeModal();render();toast('تم تحديث البيانات من نافذة أخرى');}});
  matchMedia('(prefers-color-scheme:dark)').addEventListener('change',applyTheme);
  let lastDay=J.today();document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.settings.pin&&!demo){locked=true;if(modal.open)closeModal();renderLock();}if(!document.hidden){if(lastDay!==J.today()){lastDay=J.today();selectedMonth=J.month();}render();}});
  setInterval(()=>{if(!document.hidden&&lastDay!==J.today()){lastDay=J.today();selectedMonth=J.month();render();}},30000);
  window.addEventListener('focus',()=>{if(!document.hidden&&!locked)updateBadge();});
  window.addEventListener('online',()=>sync?.tick());
  window.addEventListener('focus',()=>sync?.tick());
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync?.tick();});
  sync?.start();
  setRoute();
  if('serviceWorker' in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>{reg.addEventListener('updatefound',()=>{const sw=reg.installing;sw?.addEventListener('statechange',()=>{if(sw.state==='installed'&&navigator.serviceWorker.controller)toast('نسخة جديدة جاهزة. احفظ أي نموذج مفتوح، ثم حدّث الصفحة أو أعد فتح جيبتك.');});});return navigator.serviceWorker.ready;}).then(()=>{const status=$('#offline-status');if(status)status.textContent='جيبتك محفوظ للعمل بدون إنترنت.';}).catch(()=>{const status=$('#offline-status');if(status)status.textContent='تعذّر تجهيز العمل دون إنترنت. أعد الفتح عندما يتوفر اتصال.';});}
})();
